// Detecta reservas de la Agenda de citas de Google y extrae los datos del invitado.
// Google marca las reservas con extendedProperties.shared['goo.createdBySet'] y pone
// "Programada por / nombre / correo / teléfono" + campos del formulario en la descripción.
const PALABRA_CLAVE = 'Diagnóstico';

const e = $input.first().json;
const titulo = e.summary || '';
const descHtml = e.description || '';
const shared = (e.extendedProperties && e.extendedProperties.shared) || {};

const esReserva = Object.keys(shared).some((k) => k.startsWith('goo.createdBy'))
  || /Programada por|Booked by/i.test(descHtml)
  || (PALABRA_CLAVE && titulo.toLowerCase().includes(PALABRA_CLAVE.toLowerCase()));
if (!esReserva) return [];

// Descripción → líneas de texto plano
const lines = descHtml.replace(/<br\s*\/?>/gi, '\n').replace(/<\/p>/gi, '\n').replace(/<[^>]+>/g, '')
  .split('\n').map((s) => s.replace(/&nbsp;/g, ' ').trim()).filter(Boolean);

// Bloque "Programada por": nombre, correo, teléfono
let nombreDesc = null, correoDesc = null, telDesc = null;
const i = lines.findIndex((l) => /^(Programada por|Booked by)$/i.test(l));
if (i >= 0) {
  for (const l of lines.slice(i + 1, i + 5)) {
    if (!correoDesc && /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(l)) correoDesc = l.toLowerCase();
    else if (!telDesc && /^[+\d][\d\s()-]{6,}$/.test(l)) telDesc = l;
    else if (!nombreDesc && !/^[+\d]/.test(l)) nombreDesc = l;
  }
}
// Campos personalizados del formulario: etiqueta en <b>, valor en la línea siguiente
const campo = (re) => {
  const m = descHtml.match(new RegExp('<b>\\s*(' + re + ')[^<]*</b>\\s*\\n?\\s*([^<\\n]+)', 'i'));
  return m ? m[2].trim() : null;
};

// Invitado: asistente externo si existe; si no, el del bloque "Programada por"
const ext = (e.attendees || []).find((a) => !a.self && !a.organizer);
const correo = (ext && ext.email ? ext.email : correoDesc || '').toLowerCase();
const invitado = (ext && ext.displayName) || nombreDesc || correo || 'Invitado';
if (!correo) return [];

// Nombre entre paréntesis en el título "Diagnóstico ... (Nombre)"
const mTit = titulo.match(/\(([^)]+)\)\s*$/);

return [{ json: {
  eventId: e.id,
  titulo,
  inicio: e.start?.dateTime || e.start?.date,
  fin: e.end?.dateTime || e.end?.date,
  meet: e.hangoutLink || null,
  link: e.htmlLink,
  invitado: (mTit && mTit[1]) || invitado,
  correo,
  telefono: telDesc || campo('Tel[eé]fono|WhatsApp'),
  empresa: campo('Empresa'),
  ubicacion: campo('Ciudad'),
  servicio: campo('servicio'),
  descripcion: lines.join(' | '),
}}];

