={{ (() => { const c = $json;  const esc = (s) => String(s ?? '—').replace(/[&<>"]/g, (c) => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c])); const btn = (href, label, bg) => href ? `<td style="padding:0 8px 10px 0"><a href="${href}" style="display:inline-block;background:${bg};color:#fff;font-weight:700;font-size:14px;padding:12px 18px;border-radius:10px;text-decoration:none;white-space:nowrap;font-family:Roboto,Arial,sans-serif">${label}</a></td>` : ''; const row = (k, v) => `<tr><td style="padding:9px 12px;border-bottom:1px solid #eef0f3;color:#5f6368;font-size:13px;width:140px;vertical-align:top"><b>${k}</b></td><td style="padding:9px 12px;border-bottom:1px solid #eef0f3;font-size:14px;color:#202124">${v}</td></tr>`; const shell = ({ eyebrow, title, subtitle, rows, buttons, tip, footer }) => `<!DOCTYPE html><html><body style="margin:0;background:#f1f3f4;padding:24px 12px;font-family:Roboto,Arial,sans-serif"> <table role="presentation" cellpadding="0" cellspacing="0" width="100%" style="max-width:600px;margin:0 auto;background:#fff;border-radius:16px;overflow:hidden;box-shadow:0 2px 12px rgba(0,0,0,.06)"> <tr><td style="height:6px;background:linear-gradient(90deg,#1a73e8 0 25%,#ea4335 25% 50%,#fbbc04 50% 75%,#34a853 75% 100%);font-size:0">&nbsp;</td></tr> <tr><td style="padding:24px 28px 8px"><div style="font-size:12px;letter-spacing:.08em;text-transform:uppercase;color:#1558b8;font-weight:700">${eyebrow}</div> <h1 style="margin:6px 0 4px;font-size:22px;color:#202124">${title}</h1><div style="color:#5f6368;font-size:14px">${subtitle}</div></td></tr> <tr><td style="padding:12px 28px 4px"><table role="presentation" cellpadding="0" cellspacing="0"><tr>${buttons.join('')}</tr></table></td></tr> <tr><td style="padding:8px 28px 16px"><table role="presentation" cellpadding="0" cellspacing="0" width="100%" style="border:1px solid #eef0f3;border-radius:12px;overflow:hidden">${rows.join('')}</table></td></tr> ${tip ? `<tr><td style="padding:0 28px 20px"><div style="background:#e8f0fe;border-left:4px solid #1a73e8;border-radius:8px;padding:12px 14px;font-size:13px;color:#174ea6">${tip}</div></td></tr>` : ''} <tr><td style="padding:14px 28px 22px;border-top:1px solid #eef0f3;font-size:12px;color:#80868b">${footer}</td></tr> </table></body></html>`; 
const tz = 'America/Bogota';
const ini = DateTime.fromISO(c.inicio).setZone(tz); const fin = DateTime.fromISO(c.fin).setZone(tz);
const fecha = ini.setLocale('es').toFormat("cccc d 'de' LLLL"); const hora = `${ini.toFormat('h:mm a')} – ${fin.toFormat('h:mm a')}`;
const tel = String(c.telefono || '').replace(/\D/g, '');
const first = (c.invitado || '').split(' ')[0];
const msgWA = encodeURIComponent(`Hola ${first}, soy Carlos Andrés de Growth Digital. Confirmo nuestro diagnóstico gratuito el ${fecha} a las ${ini.toFormat('h:mm a')} (hora Colombia). Te llegará la invitación con el enlace de Google Meet. ¡Nos vemos!`);
const buttons = [
  btn(c.meet, '🎥 Abrir Meet', '#1a73e8'),
  btn(tel ? `https://wa.me/${tel}?text=${msgWA}` : null, '💬 Confirmar por WhatsApp', '#25d366'),
  btn(c.link, '📅 Ver en Calendar', '#5f6368'),
  btn('https://portal.growthdigital.marketing/', '📊 Ver en CRM', '#202124'),
];
const rows = [
  row('Cuándo', `<b>${esc(fecha)}</b><br>${esc(hora)} (hora Colombia)`),
  row('Invitado', esc(c.invitado)), row('Correo', `<a href="mailto:${esc(c.correo)}" style="color:#1a73e8">${esc(c.correo)}</a>`),
  row('WhatsApp / Tel', esc(c.telefono || '—')), row('Empresa', esc(c.empresa || '—')), row('Ciudad', esc(c.ubicacion || '—')),
  row('Servicio', esc(c.servicio || '—')), row('Evento', esc(c.titulo)),
];
const tip = `<b>Prepárate:</b> revisa su web y redes antes de la llamada, abre su ficha en el CRM (ya quedó en etapa <b>Cita agendada</b>) y confírmale por WhatsApp el día anterior.`;
return shell({ eyebrow: 'Cita agendada · Diagnóstico gratuito', title: esc(c.invitado), subtitle: `${esc(fecha)} · ${esc(hora)}`, rows, buttons, tip, footer: 'Enviado por tu automatización n8n · Growth Digital · Medellín' });
})() }}
